<?php
namespace App\Services;
use App\Exceptions\ApiException;
use App\Models\{Expense,ExpensePayment,ExpenseReversal,TillSession,User};
use App\Support\{Money,ReportMath,Quantity};
use Illuminate\Auth\Access\AuthorizationException;
use Illuminate\Support\Facades\DB;
class ExpenseService {
 public function __construct(private FinancialJournalService $journal){}
 public function view(Expense $e):array {
  $e->assertCurrentBusiness();$reversed=$this->sum(ExpenseReversal::where('expense_id',$e->id));$paid=$this->sum(ExpensePayment::where('expense_id',$e->id)->where('kind','payment'))-$this->sum(ExpensePayment::where('expense_id',$e->id)->where('kind','refund'));
  $effective=$e->amount-$reversed;
  return ['id'=>$e->publicId(),'category'=>$e->category,'description'=>$e->description,'incurred_on'=>$e->incurred_on->format('Y-m-d'),'amount'=>$e->amount,'reversed_amount'=>$reversed,'effective_amount'=>$effective,'paid_amount'=>$paid,'balance'=>max(0,$effective-$paid),'refund_due'=>max(0,$paid-$effective),'created_at'=>$e->created_at->toISOString(),
  'payments'=>ExpensePayment::where('expense_id',$e->id)->orderByDesc('id')->limit(100)->get()->map(fn($p)=>['id'=>$p->publicId(),'kind'=>$p->kind,'source'=>$p->source,'amount'=>$p->amount,'paid_on'=>$p->paid_on->format('Y-m-d'),'reference'=>$p->reference])->all()];
 }
 public function previewRecord(User $original,array $input):array{return DB::transaction(function()use($original,$input){$actor=$this->journal->lock($original);$this->owner($actor);$snapshot=$this->recordSnapshot($input);return ['snapshot'=>$snapshot,'review_hash'=>SupervisorApprovalService::snapshotHash($snapshot),'approval_required'=>false];},3);}
 public function record(User $original,array $input):array{return DB::transaction(function()use($original,$input){$actor=$this->journal->lock($original);$this->owner($actor);$snapshot=$this->recordSnapshot($input);$body=[...$snapshot,'review_hash'=>$input['review_hash']??''];if($old=$this->journal->replay($actor,'expense_record',$body))return $old;if(!hash_equals(SupervisorApprovalService::snapshotHash($snapshot),$body['review_hash']))throw new ApiException('EXPENSE_CHANGED','Review these expense details before committing.',409);$expense=Expense::create([...array_diff_key($snapshot,['operation_id'=>1]),'actor_id'=>$actor->id]);return $this->journal->remember($actor,'expense_record',$body,['expense'=>$this->view($expense)]);},3);}
 private function recordSnapshot(array $input):array{$snapshot=['operation_id'=>strtolower($input['operation_id']),'category'=>trim($input['category']),'description'=>trim($input['description']),'incurred_on'=>$input['incurred_on'],'amount'=>Money::amount($input['amount'])];if($snapshot['amount']===0)throw new ApiException('VALIDATION_ERROR','Enter a positive expense amount.',422);return $snapshot;}
 public function previewReversal(User $original,Expense $expense,array $input):array{return DB::transaction(function()use($original,$expense,$input){$actor=$this->journal->lock($original);$this->owner($actor);$expense->refreshForUpdate();$snapshot=$this->reversalSnapshot($expense,$input);return ['snapshot'=>$snapshot,'review_hash'=>SupervisorApprovalService::snapshotHash($snapshot),'approval_required'=>false];},3);}
 public function reverse(User $original,Expense $expense,array $input):array{return DB::transaction(function()use($original,$expense,$input){$actor=$this->journal->lock($original);$this->owner($actor);$expense->refreshForUpdate();$body=['operation_id'=>strtolower($input['operation_id']),'expense_id'=>$expense->publicId(),'amount'=>Money::amount($input['amount']),'reason'=>trim($input['reason']),'reversed_on'=>$input['reversed_on'],'review_hash'=>$input['review_hash']??''];if($old=$this->journal->replay($actor,'expense_reverse',$body))return $old;$snapshot=$this->reversalSnapshot($expense,$input);if(!hash_equals(SupervisorApprovalService::snapshotHash($snapshot),$body['review_hash']))throw new ApiException('EXPENSE_CHANGED','The expense changed. Review this reversal again.',409);ExpenseReversal::create([...array_diff_key($body,['operation_id'=>1,'expense_id'=>1,'review_hash'=>1]),'expense_id'=>$expense->id,'actor_id'=>$actor->id]);return $this->journal->remember($actor,'expense_reverse',$body,['expense'=>$this->view($expense)]);},3);}
 private function reversalSnapshot(Expense $expense,array $input):array{if($input['reversed_on']<$expense->incurred_on->format('Y-m-d'))throw new ApiException('VALIDATION_ERROR','A reversal cannot precede the expense date.',422);$v=$this->view($expense);$amount=Money::amount($input['amount']);if($amount<1||$amount>$v['effective_amount'])throw new ApiException('VALIDATION_ERROR','The reversal exceeds the remaining recorded expense.',422);return ['operation_id'=>strtolower($input['operation_id']),'expense_id'=>$expense->publicId(),'amount'=>$amount,'reason'=>trim($input['reason']),'reversed_on'=>$input['reversed_on'],'effective_amount'=>$v['effective_amount'],'paid_amount'=>$v['paid_amount'],'refund_due'=>$v['refund_due']];}
 public function previewPayment(User $original,Expense $expense,array $input):array{return DB::transaction(function()use($original,$expense,$input){$actor=$this->journal->lock($original);$this->owner($actor);$expense->refreshForUpdate();return $this->paymentReview($actor,$expense,$input);},3);}
 public function settle(User $original,Expense $expense,array $input):array{return DB::transaction(function()use($original,$expense,$input){$actor=$this->journal->lock($original,'manage_settings',$input['approval_token']??null);$this->owner($actor);$expense->refreshForUpdate();$body=array_diff_key($input,['review_hash'=>1,'approval_token'=>1]);$body['expense_id']=$expense->publicId();$body['operation_id']=strtolower($body['operation_id']);if($old=$this->journal->replay($actor,'expense_settle',$body))return $old;$review=$this->paymentReview($actor,$expense,$body);if(!hash_equals($review['review_hash'],$input['review_hash']))throw new ApiException('EXPENSE_CHANGED','The expense balance changed. Review this payment again.',409);
  $write=function()use($actor,$expense,$body,$review){$s=$review['snapshot'];$till=$s['till_id']?(new TillSession)->resolveRouteBinding($s['till_id']):null;
   if($till)app(TillService::class)->recordCash($actor,$till,$s['kind']==='refund'?'expense_refund':'paid_out',$s['amount'],$s['operation_id'],'Expense '.$expense->publicId());
   ExpensePayment::create(['expense_id'=>$expense->id,'actor_id'=>$actor->id,'parent_payment_id'=>$s['payment_id']?(new ExpensePayment)->resolveRouteBinding($s['payment_id'])->id:null,'till_session_id'=>$till?->id,'kind'=>$s['kind'],'source'=>$s['source'],'amount'=>$s['amount'],'paid_on'=>$s['paid_on'],'reference'=>$s['reference'],'reference_hash'=>$s['reference']?hash('sha256',$s['kind'].'|'.$s['reference']):null]);return $this->journal->remember($actor,'expense_settle',$body,['expense'=>$this->view($expense)]);};
  if($review['approval_required']){if(empty($input['approval_token']))throw new ApiException('APPROVAL_REQUIRED','Approve this till-funded expense payment with the owner authenticator.',403);return app(SupervisorApprovalService::class)->execute($actor,$input['approval_token'],'manage_settings',$body['operation_id'],$review['snapshot'],$write);}if(isset($input['approval_token']))throw new ApiException('VALIDATION_ERROR','This external payment record needs no till approval.',422);return $write();},3);}
 private function paymentReview(User $actor,Expense $expense,array $input):array {
  $v=$this->view($expense);$kind=$input['kind'];$amount=Money::amount($input['amount']);$source=$input['source'];$till=null;$parent=null;
  if($amount<1||$amount>($kind==='refund'?$v['refund_due']:$v['balance']))throw new ApiException('VALIDATION_ERROR','The payment exceeds the remaining balance or refund due.',422);
  if($kind==='refund'){$parent=(new ExpensePayment)->resolveRouteBindingQuery(ExpensePayment::where('expense_id',$expense->id)->where('kind','payment'),$input['payment_id']??'')->lockForUpdate()->firstOrFail();$remaining=$parent->amount-$this->sum(ExpensePayment::where('parent_payment_id',$parent->id)->where('kind','refund'));if($source!==$parent->source||$amount>$remaining)throw new ApiException('VALIDATION_ERROR','Refund the original payment source within its remaining amount.',422);}elseif(isset($input['payment_id']))throw new ApiException('VALIDATION_ERROR','A payment reference belongs only to an expense refund.',422);
  if($source==='till'){$till=(new TillSession)->resolveRouteBindingQuery(TillSession::query(),$input['till_id']??'')->lockForUpdate()->firstOrFail();if($till->cashier_id!==$actor->id||$till->status!=='open')throw new AuthorizationException;$cash=app(TillService::class)->view($till)['expected_cash'];if($kind==='payment'&&$amount>$cash)throw new ApiException('INSUFFICIENT_CASH','There is not enough cash in your open till.',409);}elseif(isset($input['till_id']))throw new ApiException('VALIDATION_ERROR','External payment records cannot change drawer cash.',422);
  $reference=$source==='till'?null:trim($input['reference']??'');if($reference&&ExpensePayment::where('source',$source)->where('reference_hash',hash('sha256',$kind.'|'.$reference))->exists())throw new ApiException('PAYMENT_REFERENCE_REUSED','This completed external reference was already recorded.',409);if($source!=='till'&&$reference==='')throw new ApiException('VALIDATION_ERROR','Enter the completed external payment reference.',422,'reference');
  $s=['operation_id'=>strtolower($input['operation_id']),'expense_id'=>$expense->publicId(),'kind'=>$kind,'source'=>$source,'amount'=>$amount,'paid_on'=>$input['paid_on'],'reference'=>$reference,'payment_id'=>$parent?->publicId(),'till_id'=>$till?->publicId(),'till_revision'=>$till?->revision,'balance'=>$v['balance'],'refund_due'=>$v['refund_due']];
  return ['snapshot'=>$s,'review_hash'=>SupervisorApprovalService::snapshotHash($s),'approval_required'=>$source==='till'&&$kind==='payment'];
 }
 private function sum($q):int{if(DB::transactionLevel()<1)return Money::amount(Quantity::parse((string)$q->sum('amount')));$total=0;foreach($q->orderBy('id')->lockForUpdate()->get(['amount'])as$row)$total=Money::amount(\App\Support\ExactMath::add($total,Money::amount($row->amount)));return $total;}
 private function owner(User $u):void{if(!$u->hasRole('owner'))throw new AuthorizationException;}
}
